// We use the Verus verification framework
use vstd::prelude::*;

verus! {

    /// Given a non-empty slice `a` of 32-bit signed integers,
    /// returns an index of a maximum element.
    /// Requires:
    ///  - `a.len() > 0`
    /// Ensures:
    ///  - `result < a.len()`
    ///  - For all `j < a.len()`, `a[result] >= a[j]`.
    pub fn find_max(a: &[i32]) -> usize
        requires
            a.len() > 0,
        ensures
            result < a.len(),
        ensures
            forall |j: usize| j < a.len() ==> a[result] >= a[j],
    {
        let n = a.len();
        // We will scan from i = 1 up to n, tracking the index of the current maximum.
        let mut i: usize = 1;
        let mut max_idx: usize = 0;

        // Loop invariant:
        //  1) i is between 0 and n
        //  2) max_idx < i
        //  3) a[max_idx] is >= every element among a[0..i)
        // Decreases ensures termination.
        while i < n
            invariant
                i <= n,
            invariant
                max_idx < i,
            invariant
                forall |j: usize| j < i ==> a[max_idx] >= a[j],
            decreases
                n - i,
        {
            // If the current element a[i] is strictly greater than our known maximum,
            // update max_idx.
            if a[i] > a[max_idx] {
                max_idx = i;
            }
            i += 1;
        }

        // After the loop, i == n, and the invariant tells us:
        //   max_idx < n
        //   for all j < n, a[max_idx] >= a[j]
        max_idx
    }

}